#include <iostream>

// Demonstrating that complex control structures (for, switch)
// are fundamentally equivalent to minimal structures (sequence, if, while).
int main() {
    int target = 3;
    if (std::cin >> target) {
        // Pattern 1: Canonical structured loop using solely 'while', 'if', and sequence
        int count = 0; // Initialization (sequence)
        while (count < target) { // Repetition (while)
            if (count % 2 == 0) { // Selection (if)
                std::cout << "Even: " << count << "\n";
            }
            if (count % 2 != 0) { // Selection (if) replacing else
                std::cout << "Odd: " << count << "\n";
            }
            count = count + 1; // Increment (sequence)
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    int base = 2;
    int maxExponent = 3;
    if (std::cin >> base >> maxExponent) {
        std::cout << std::left << std::setw(6) << "Exp"
                  << std::right << std::setw(10) << "Power" << "\n";

        for (int exp = 0; exp <= maxExponent; ++exp) {
            if (exp == 2 && base == 0) {
                continue; // Skip specific condition
            }
            double val = std::pow(base, exp);
            std::cout << std::left << std::setw(6) << exp
                      << std::right << std::setw(10) << static_cast<long long>(val) << "\n";
        }
    }
    return 0;
}
